#!/bin/bash
# 0.4.52 pre-dry-run refresh of the shared Mac ~/.npm starter packuments (0.4.30 / 0.4.41 dr3 / 0.4.43 dr2 lessons: a stale
# packument makes the Darwin starters proof's --prefer-offline install pick an old version; e.g. node-forge 1.4.0 -> audit
# "fix available"). No 0.4.52 Darwin stage exists before dry run 1, so each starter is generated by the commit's own
# target/debug/snapback4 (native cargo-build at 107a413c29) with the proof's flags, then package.json points at the prepared
# client/Expo tarballs (client-0.4.52) and the tree is resolved ONLINE (0.4.52: init runs with SNAPBACK4_INIT_INSTALL=0, since init now installs the frontend itself and that install cannot resolve the unpublished 0.4.52) (--package-lock-only, metadata only), then --prefer-offline.
# The unpublished darwin-arm64 0.4.52 optional dependency is expected to be skipped. Scratch dirs removed; no source/publish state touched.
export PATH=/Users/ccheever/.volta/tools/image/node/24.18.0/bin:/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin
W=$HOME/sb4-pub-0444-wt/snapback4; S=$W/target/publication/client-0.4.52; B=$W/target/debug/snapback4
R=$HOME/sb4-pub-0452/npm-refresh; rm -rf $R; mkdir -p $R; O=$HOME/sb4-pub-0452/isolated/npm-refresh-${REFRESH_TAG:-a2}; mkdir -p $O
for c in "web|--web" "web-online|--web --online" "expo|--expo" "web-chat|--web --template chat" "expo-chat|--expo --template chat" "expo-social|--template social"; do
  id=${c%%|*}; flags=${c#*|}; d=$R/$id; mkdir -p $d; cd $d; echo '{"private":true}' > package.json
  SNAPBACK4_INIT_INSTALL=0 $B init $flags > $O/$id-init.log 2>&1 || { echo "$id init FAILED"; tail -3 $O/$id-init.log; continue; }
  node -e 'const fs=require("fs"),[,c,e,kind]=process.argv;const p=JSON.parse(fs.readFileSync("package.json"));p.dependencies=p.dependencies||{};p.dependencies.snapback4="file:"+c;if(kind==="expo")p.dependencies["snapback4-expo"]="file:"+e;fs.writeFileSync("package.json",JSON.stringify(p,null,2))' $S/snapback4-0.4.52.tgz $S/snapback4-expo-0.4.52.tgz ${id%%-*}
  npm install --package-lock-only --prefer-online --ignore-scripts --no-audit --no-fund > $O/$id-online.log 2>&1; on=$?
  rm -f package-lock.json
  npm install --package-lock-only --prefer-offline --ignore-scripts --no-audit --no-fund > $O/$id-offline.log 2>&1; off=$?
  forge=$(node -e 'try{const l=require("./package-lock.json");console.log(l.packages["node_modules/node-forge"]?.version??"none")}catch{console.log("?")}')
  echo "$id online-resolve rc=$on prefer-offline-resolve rc=$off node-forge=$forge $(grep -m1 -o 'E[A-Z0-9]*' $O/$id-offline.log)"
done
cd $HOME; rm -rf $R; npm view node-forge version --offline 2>&1 | tail -1; npm view vite version --offline 2>&1 | tail -1; echo refresh-done
